//! Original packed fixture generated by Git's documented fast-import stream.
use std::io::Write;
use std::path::Path;
use std::process::{Command, Stdio};

/// Creates exactly `count` packed objects: distinct blobs, one tree and one commit.
pub fn populate(path: &Path, count: u32) {
    let mut stream = Vec::new();
    for i in 0..count - 2 {
        stream.extend_from_slice(b"blob\n");
        if i == 0 {
            stream.extend_from_slice(b"mark :1\n");
        }
        stream.extend_from_slice(b"data 4\n");
        stream.extend_from_slice(&i.to_le_bytes());
        stream.push(b'\n');
    }
    stream.extend_from_slice(b"commit refs/heads/main\ncommitter Fixture <fixture@example.com> 1 +0000\ndata 0\nM 100644 :1 file\n\n");
    let mut child = Command::new("git")
        .arg("--git-dir")
        .arg(path)
        .args(["-c", "gc.auto=0", "fast-import", "--quiet"])
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", path.join("absent-global-config"))
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(&stream).unwrap();
    let output = child.wait_with_output().unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
}
